class RecoveryManager:
    """
        A class to manage the recovery state of the UE-proxy service.

        Attributes
        ----------
        _recovery : bool
            A private attribute to store the recovery state.

        Methods
        -------
        recovery()
            Getter method for the recovery state.
        recovery(value: bool)
            Setter method for the recovery state.
    """
    def __init__(self):
        """
        Initializes the RecoveryManager with the recovery state set to False.
        """
        self._recovery = False

    @property
    def recovery(self):
        """
        Gets the current recovery state.

        Returns
        -------
        bool
        The current recovery state.
        """
        return self._recovery

    @recovery.setter
    def recovery(self, value):
        """
        Sets the recovery state.

        Parameters
        ----------
        value : bool
            The new recovery state.
        """
        self._recovery = value


recovery_manager = RecoveryManager()


@app.on_event("startup")
async def startup():
    """Startup event handler"""
    global ueproxy_config, ueproxy_range, logs_storage_duration, logs_storage_limit, logger, ueproxy_naa_protocol, \
        at_ue_manager, stream_logs, pyz_start_timeout
    releases_location = _get_server_path(for_storing="releases")
    os.makedirs(releases_location, exist_ok=True)
    logs_location = _get_server_path(for_storing="logs")
    os.makedirs(logs_location, exist_ok=True)
    logger = ProxyMngrLogger(log_file_name="proxy_mngr.log", log_base_dir=_get_server_storage())
    logger.log("\n", logging.DEBUG)
    logger.log("starting UE-proxy manager service", logging.INFO)
    defaults = ('{"ssl_keyfile": "", "ssl_certfile": "", "ssl_client_certbundle": "", "ueproxy_ports_range": "",'
                '"ueproxy_config": "", "logs_storage_duration": 7, "logs_storage_limit": 10, '
                '"proxy_mngr_artifactory": null, "ueproxy_naa_protocol": "usb_byte", "at_ue_manager": false, '
                '"stream_logs": false, "pyz_start_timeout": 60}')
    options = json.loads(os.environ.get('MNGR_CMD_LINE_OPTIONS', defaults))
    _clear_shiv_root_dir()
    __configure_proxy_mngr_artifactory_url(options['proxy_mngr_artifactory'])
    logger.log(f"selected PROXY_MNGR_ARTIFACTORY path: {PROXY_MNGR_ARTIFACTORY}", logging.INFO)
    ssl_files['ssl_keyfile'] = options['ssl_keyfile']
    ssl_files['ssl_certfile'] = options['ssl_certfile']
    ssl_files['ssl_client_certbundle'] = options['ssl_client_certbundle']
    ueproxy_config = options['ueproxy_config']
    ueproxy_range = options['ueproxy_ports_range']
    logs_storage_duration = int(options['logs_storage_duration'])
    logs_storage_limit = int(options["logs_storage_limit"])
    ueproxy_naa_protocol = options["ueproxy_naa_protocol"]
    at_ue_manager = options["at_ue_manager"]
    stream_logs = options["stream_logs"]
    pyz_start_timeout = options["pyz_start_timeout"]
    _check_windows_long_paths_enabled(logger)
    _configure_api_external_loggers()
    shared_db.logger = logger


@app.on_event("shutdown")
async def shutdown():
    """Stop all running UE-proxy servers"""
    for ue_type in list(ueproxy_pool.services.keys()):
        port = ueproxy_pool.get_service_port(ue_type)
        await _stop_service(int(port))  # TODO: add timeout
    ueproxy_pool.services.clear()


