async def memory_logs() -> list:
    """
    Retrieve in-memory logs from specified loggers.

    This function collects logs from the 'uvicorn' and 'uvicorn.access' loggers,
    as well as any other loggers that are instances of `InMemoryHandler`.
    The logs are stored in a deque with a maximum length of 500 to limit memory usage.

    :return: A sorted list of log entries, each containing a timestamp and log message.
    :rtype: list
    """
    if stream_logs:
        loggers = ['uvicorn', 'uvicorn.access']
        logs = deque(maxlen=500)
        for logger_name in loggers:
            if isinstance(logger_name, str):
                log = logging.getLogger(logger_name)
                for handler in log.handlers:
                    if isinstance(handler, InMemoryHandler):
                        logs.extend(handler.get_logs())
            else:
                logs.extend(logger_name.get_logs())
        return sorted(logs, key=lambda log: log['timestamp'])


@app.websocket("/proxy_mngr_logs")
async def get_memory_logs(websocket: WebSocket) -> None:
    """
    WebSocket endpoint to stream in-memory logs to the client.

    This function accepts a WebSocket connection, retrieves in-memory logs periodically,
    and sends them to the connected client. It continues to send updates every 5 seconds
    until the client disconnects.

    :param websocket: WebSocket connection instance.
    :type websocket: WebSocket
    """
    if not stream_logs:
        await websocket.close()
        return
    try:
        await websocket.accept()
        prev_logs = []
        while True:
            logs = await memory_logs()
            if logs != prev_logs:
                await websocket.send_json(logs)
                prev_logs = logs
            await asyncio.sleep(5)
    except WebSocketDisconnect:
        logger.log("WebSocket Client disconnected", logging.INFO)


@app.post("/releases/download", tags=["Storage"])
async def download_ueproxy_specific_release(release_package: ReleasePackage) -> None:
    """
    Download specific version of `ueproxy` from artifactory

        /releases/ueproxy-0.7.0-py38-macos_10.9.pyz - download that specific release file
    """
    release_filename = _create_release_package_name(release_package)
    release_file_location = _get_release_path(rel_filename=release_filename)

    if os.path.isfile(release_file_location):
        reason = f"{release_filename} already on UE PC"
        logger.log(reason, logging.DEBUG)
        return
    logger.log(f"Trying to download Ue-Proxy release {release_filename}.", logging.INFO)

    resources_url = _get_resources_url_from_package(package=release_package, search_name=release_filename)

    available_releases = _get_all_filenames_from_server(url=resources_url, file_extension=release_package.rel_format)

    if release_filename in available_releases:
        proxies = {
            "http": "",
            "https": "",
        }
        response = requests.get(url=f"{resources_url}/{release_filename}", proxies=proxies)
        response.raise_for_status()

        async with aiofiles.open(release_file_location, mode='wb') as new_release_file:
            await new_release_file.write(response.content)

        if os.path.isfile(release_file_location) and os.path.getsize(release_file_location) > 0:
            _remove_redundant_proxy_releases(_build_release_validation_re(prefix=r'', suffix=r'$'))
            return
    reason = f"{release_filename} unavailable at server"
    logger.log(reason, logging.DEBUG)
    raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=reason)


