@app.post("/releases", tags=["Storage"])
async def upload_ueproxy_release(release_file: UploadFile = File(...)):
    """
    Upload `ueproxy` release to UE PC

    Release filename must follow format:

        ueproxy-{ver}-py{python_ver}-{os_name}_{os_ver}.{rel_format}
    """
    rel_filename = release_file.filename
    release_validator = _build_release_validation_re(prefix=r'', suffix=r'$')
    match = release_validator.match(rel_filename)
    if match:
        # release format validated - store it
        release_filename_path = _get_release_path(rel_filename)
        if os.path.isfile(release_filename_path):
            reason = f"{rel_filename} already exists - can't overwrite"
            raise HTTPException(status_code=status.HTTP_406_NOT_ACCEPTABLE, detail=reason)
        async with aiofiles.open(release_filename_path, mode='wb') as new_release_file:
            content = await release_file.read()  # read from SpooledTemporaryFile
            await new_release_file.write(content)
    else:
        _report_incorrect_release_format(rel_filename, expected_format=release_validator.pattern)
    _remove_redundant_proxy_releases(release_validator)


