@app.post("/releases/autoupdate", tags=["Storage"])
async def turn_on_off_autoupdate_ueproxy(method_details: AutoUpdate) -> str:
    """
    Turn on/off automatic updating `ueproxy` releases from artifactory

    method: start/stop
    :param method_details: AutoUpdate object
    :return: str: Information abot autoupdate set
    :raise: HTTPException for 404 not found error
    """
    new_status = {"start": True, "stop": False}.get(method_details.method)
    if new_status is None:
        reason = f'Method "{method_details.method}" doesnt exists'
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=reason)
    global autoupdate
    autoupdate = new_status
    return f"Autoupdate {'activated' if autoupdate else 'deactivated'}"


