@app.post("/releases/download/latest", tags=["Storage"])
async def download_latest_ueproxy_release(types: LatestPackage) -> str:
    """
    Download the latest `ueproxy` release from artifactory
    """
    ue_type = __normalize_ue_type(types.ue_type)
    resources_url = _get_resources_url_from_package(package=types, search_name=ue_type)
    latest_release_on_uepc = _get_latest_release_from_ue_pc(ue_type)
    available_releases = _get_all_filenames_from_server(url=resources_url, file_extension=types.rel_format)
    latest_release = _check_for_newer_release_on_artifactory(available_releases=available_releases,
                                                             latest_release_on_uepc=latest_release_on_uepc,
                                                             ue_type=ue_type)

    if latest_release is not None:
        release_validator = _build_release_validation_re()
        release_package = _get_release_info(search_through=latest_release, release_validator=release_validator)
        await download_ueproxy_specific_release(release_package)
        return latest_release
    logger.log(f"Cannot find newer release for {ue_type} than {latest_release_on_uepc}.", logging.DEBUG)
    return 'Latest release already on pc'


