@app.get("/services/logs", tags=["Execution"], include_in_schema=False)
async def download_execution_logs(ue_type, port):
    """
    Download proxy manager logs with latest ueproxy execution logs.

    :param ue_type: Type of Ue which was used during the test
    :param port: Port number on which ueproxy service used in test has been deployed
    :return: Zip file
    """
    service_files_dir = os.path.join(os.getcwd(), '.ueproxyservice')
    ueproxy_logs_dir = os.path.join(service_files_dir, 'logs')
    to_archive_dir = os.path.join(service_files_dir, 'to_archive_logs')
    proxy_mngr_to_archive_dir = os.path.join(to_archive_dir, 'proxy_mngr_logs')
    ueproxy_to_archive_dir = os.path.join(to_archive_dir, 'ueproxy_logs')
    zip_name = 'proxy_mngr_logs.zip'

    ueproxy_logs = os.listdir(ueproxy_logs_dir)
    matched_logs = __select_matched_logs(ueproxy_logs, port, ue_type)

    if matched_logs:
        latest_ueproxy_logs_folder = __get_latest_created_catalogue_from(selected_catalogues=matched_logs,
                                                                         path=ueproxy_logs_dir)
        __create_directory_if_not_exist(to_archive_dir)
        try:
            # Copy ueproxy logs folder content
            shutil.copytree(src=os.path.join(ueproxy_logs_dir, latest_ueproxy_logs_folder),
                            dst=ueproxy_to_archive_dir)
        except Exception as exc:
            logger.log(f"Copying ueproxy log files failed. See: {exc}", logging.DEBUG)

        try:
            # Copy proxy manager log
            __create_directory_if_not_exist(proxy_mngr_to_archive_dir)
            shutil.copy2(src=os.path.join(service_files_dir, 'proxy_mngr.log'),
                         dst=proxy_mngr_to_archive_dir)
        except Exception as exc:
            logger.log(f"Copying proxy manager log files failed. See: {exc}", logging.DEBUG)

        try:
            _zip_folder(folder_path=to_archive_dir,
                        zip_file_path=os.path.join(service_files_dir, zip_name))
        except Exception as exc:
            logger.log(f"Zipping proxy manager log files failed. See: {exc}", logging.DEBUG)
    else:
        logger.log(f"There is no log to download with specified match: {(ue_type, port)}", logging.DEBUG)

    try:
        __remove_directory_with_content_if_exists(to_archive_dir)
    except Exception as exc:
        logger.log(f"Removing to_archive_logs catalogue failed. See: {exc}", logging.DEBUG)

    return FileResponse(path=os.path.join(service_files_dir, zip_name),
                        media_type="application/octet-stream",
                        filename=zip_name)


@app.post("/services/start", tags=["Execution"], response_model=ServiceDetails)
async def start_ueproxy_service(request: Request, ueproxy_package: ReleasePackage):
    """
    Start `ueproxy` release as service at UE PC

    Release filename must follow format:

        ueproxy-{ver}-py{python_ver}-{os_name}_{ue_type}_{os_ver}.{rel_format}
    :param request: Request object
    :param ueproxy_package: StartUeproxyServer object
    :return: Server process Id information
    """
    global last_working_proxy
    rel_filename = _create_release_package_name(ueproxy_package)
    ue_type = __normalize_ue_type(ueproxy_package.ue_type)
    ue_proxy_service = await __get_ueproxy_with_specific_access_layer_if_is_running(ue_type, timeout=10, interval=0.5)
    url = request.url.hostname
    if ue_proxy_service:
        ueproxy_pool.add_test_in_progress(ue_type)
        return ue_proxy_service.info
    else:
        await _check_android_naa_protocol_can_start(ue_type)
        _clear_shiv_root_dir(ue_type)
        if str(url) in ["localhost", "127.0.0.1"]:
            logger.log("You already have a running session connected via 'localhost', "
                       "so it is being changed to external host IP.", logging.WARNING)
            url = socket.gethostbyname(socket.gethostname())
        release_validator = _build_release_validation_re(prefix=r'', suffix=r'$')
        match = release_validator.match(rel_filename)
        if not match:
            _report_incorrect_release_format(rel_filename, expected_format=release_validator.pattern)
        # release format validated - start it
        python_ver = match.group(3)
        _assert_release_file_exists(rel_filename)
        # UE-proxy works on same scheme/hostname as UE-proxy-mngr
        # Moreover, it always uses port as HTTP port - if HTTPS is requested then we have 2 ports:
        #   {port} for http-redirection-to-https and {port+1} for https
        global ueproxy_range
        port = _select_port_from_range(ueproxy_range)
        port4url = (port + 1) if request.url.scheme == 'https' else port
        ueproxy_url = f"{request.url.scheme}://{url}:{port4url}"
        # _assert_url_not_occupied(ueproxy_url, rel_filename)

        # create inactive ueproxy service
        await ueproxy_pool.create_service(ue_type=ue_type)

        # here we should recognize release format and start it accordingly (right now we have just .pyz)
        # activate ueproxy service
        try:
            pid, process, details, console_log = await _start_pyz_release(python_ver, ueproxy_url, port,
                                                                          rel_filename, ue_type)
        except Exception as e:
            logger.log(f"Ue-Proxy service didn't start up. Reason: {e}.", logging.DEBUG)
            last_working_package = last_working_proxy.get(ueproxy_package.ue_type, None)
            if isinstance(last_working_package, ReleasePackage) and ueproxy_package != last_working_package:
                logger.log(f"Starting last working proxy: {last_working_package}", logging.DEBUG)
                await start_ueproxy_service(request, last_working_package)
                recovery_manager.recovery = True
                return
            else:
                logger.log("No last working proxy or last working proxy also doesn't work", logging.DEBUG)
                logger.log(f"Proxy service doesn't start correctly port: {port} removed from the reserved ports.",
                             logging.DEBUG)
                reserved_ports.discard(port)
                await shared_db.naa_protocol.remove_by_port(port)
                raise
        ueproxy_pool.activate_service(ue_type, process, details, console_log)
        await shared_db.naa_protocol.add_or_update(port=port, naa_protocol=ueproxy_naa_protocol, pid=pid, access=ue_type)
        last_working_proxy[ueproxy_package.ue_type] = ueproxy_package
        logger.log(f"Ue-Proxy service for {ue_type} started on port: {port}.", logging.DEBUG)
        return ueproxy_pool.services[ue_type].info


@app.post("/services/stop", tags=["Execution"])
async def stop_service(service_details: UeproxyServerDetails):
    """
    Stop service running at UE PC

        /services/{port}                             - stop service running under specific port
    """
    global reserved_ports
    ue_type_to_del = None
    port = service_details.port
    for ue_type in list(ueproxy_pool.services.keys()):
        if port == ueproxy_pool.get_service_port(ue_type):
            logger.log(f"Stop proxy server for following port: {port} and ue type: {ue_type}.", logging.DEBUG)
            await _stop_service(port, timeout=10)
            ue_type_to_del = ue_type
    ueproxy_pool.delete_service(ue_type_to_del)
    if port in reserved_ports:
        logger.log(f"Stop service - remove port: {port} from reserved ports.", logging.DEBUG)
        reserved_ports.remove(port)
    else:
        logger.log(f"Stop service - port: {port} is not in reserved ports.", logging.DEBUG)


@app.post("/services/release", tags=["Execution"])
async def release_ueproxy_service(service_details: UeproxyServerDetails):
    """
    Mark ueproxy service run at specific port as inactive
    """
    if recovery_manager.recovery:
        logger.log("Recovery mode is on. Service won't be released.", logging.DEBUG)
        recovery_manager.recovery = False
    else:
        port = service_details.port
        for ue_type in list(ueproxy_pool.services.keys()):
            if port == ueproxy_pool.get_service_port(ue_type):
                ueproxy_pool.deactivate_service(ue_type)


@app.post("/artifactory/get/package_list", include_in_schema=False)
async def get_ueproxy_release_list(types: LatestPackage) -> list:
    """
    Get `ueproxy` releases list from artifactory regarding ue_type
    """
    ue_type = __normalize_ue_type(types.ue_type)
    resources_url = _get_resources_url_from_package(package=types, search_name=ue_type)
    available_releases = _get_all_filenames_from_server(url=resources_url, file_extension=types.rel_format)
    available_releases = [rel for rel in available_releases
                          if rel.startswith("ueproxy-") and f"-py{PYTHON_VERSION}-{__get_os_name()}-{ue_type}-" in rel]
    logger.log(f"Got release list for ue_type='{ue_type}' with format='{types.rel_format}': {available_releases}",
               logging.DEBUG)
    return list(reversed(available_releases))


@app.post("/artifactory/get/url", include_in_schema=False)
async def get_artifactory_address(types: LatestPackage) -> str:
    """
    Get `ueproxy` releases list from artifactory regarding ue_type
    """
    ue_type = __normalize_ue_type(types.ue_type)
    resources_url = _get_resources_url_from_package(package=types, search_name=ue_type)
    logger.log(f"Got artifactory url for ue_type='{ue_type}' with format='{types.rel_format}': {resources_url}",
               logging.DEBUG)
    return resources_url


# --------------------- private
def _get_all_running_services():
    """
    Get all running services

    :return dict: dictionary of all running services
    """
    return {port: (ueproxy_pool.services[ue_type].info,
                   ueproxy_pool.services[ue_type].status)
            for ue_type in list(ueproxy_pool.services.keys())
            if (port := ueproxy_pool.get_service_port(ue_type)) is not None}

def _is_port_available(port: int):
    """
    Check if port is available

    :param port: port number
    :return: True if port is available, False otherwise
    """
    connections = psutil.net_connections()
    ports_in_use = [conn.laddr.port for conn in connections if conn.status == psutil.CONN_LISTEN]
    return True if port not in ports_in_use else False


def _select_port_from_range(ports_range: List[str]):
    """
    Select port from range of ports

    :param ports_range: list of ports range
    :return: port number
    """
    global reserved_ports
    ports_from_range = list(range(int(ports_range[0]), int(ports_range[1])+1))
    filtered_numbers = [num for num in ports_from_range if num not in reserved_ports]

    attempts = 5
    for attempt in range(attempts):
        port = random.choice(filtered_numbers)
        if _is_port_available(port):
            reserved_ports.add(port)
            return port
        else:
            logger.log(f"Port: {port} already occupied. Attempt: {attempt}", logging.DEBUG)
    raise UeproxyPortException(f"All ports from {ports_range} already in use! "
                               f"After {attempts} attempts, proxy mngr wasn't able to chose available port.")


def _get_all_filenames_from_server(url: str, file_extension: str = '.pyz') -> List[str]:
    """
    Get all filenames from server

    :param url: url to server
    :param file_extension: file extension to filter
    :return: list of filenames
    """
    filenames = []
    proxies = {
        "http": "",
        "https": "",
    }
    response = requests.get(url, proxies=proxies)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, 'html.parser')

    for link in soup.find_all('a'):
        file_url = link.get('href')
        if file_url.endswith(file_extension):
            filenames.append(os.path.basename(file_url))
    return filenames


def _create_release_package_name(release_package: ReleasePackage):
    """
    Create release package name based on provided parameters

    :param release_package: ReleasePackage object
    :return: release package name
    """
    if release_package:
        return f"ueproxy-{release_package.ver}-py{release_package.python_ver}-{release_package.os_name}-" \
               f"{release_package.ue_type}-{release_package.os_ver}.{release_package.rel_format}"
    return None


def _get_resources_url_from_package(package: Union[ReleasePackage, LatestPackage], search_name: str):
    """
    Get resources url path from release_package

    :param package: release package
    :param search_name: Search name
    :return: str: Resources URL to artifactory directory containing packages
    :raise: HTTPException for 404 not found error
    """
    global is_custom_artifactory
    if is_custom_artifactory:
        return PROXY_MNGR_ARTIFACTORY

    ue_type = __normalize_ue_type(package.ue_type)
    if ue_type in ('android', 'at', 'fastmile', 'mtk', 'quectel', 'simcom','sequans'):
        return f"{PROXY_MNGR_ARTIFACTORY}/{ue_type}"
    elif ue_type == 'iphone':
        return f"{PROXY_MNGR_ARTIFACTORY}"
    else:
        reason = f"{search_name} package(s) unavailable at server"
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=reason)


def _get_releases() -> List:
    """
    Get info about releases available at UE PC

        /releases/                                   - all releases at UE PC
    """
    # (list names or names + available-access-layers ?, maybe ?with-access-layer=android)
    release_validator = _build_release_validation_re(prefix=r'[\\/]releases[\\/]', suffix='')
    available_releases = []
    for path in _get_server_files():
        # filter on path like '.uservice/releases/ueproxy-0.7.0-py38-macos_10.9.pyz'
        rel_info = _get_release_info(path, release_validator)
        release_filename = _create_release_package_name(rel_info)
        if release_filename:
            available_releases.append(release_filename)
    return available_releases


def __get_os_name():
    """
    Get OS name on UE PC

    :return: String name of OS (very short info)
    """
    os_name = platform.system()[:3].lower() if "darwin" not in platform.system().lower() else "macos"
    return "linux" if os_name == "lin" else os_name


def __normalize_ue_type(ue_type: str):
    """
    Normalize UE type (esp. for AT packages)
    :param ue_type: UE type
    :return: normalized UE type name
    """
    return 'at' if ue_type.lower() == 'atcmd' else ue_type.lower()


def _get_latest_release_from_ue_pc(ue_type):
    """
    Get the latest release from UE PC

    :param ue_type: UE type
    :return: latest release
    """
    releases = _get_releases()  # Get releases from UE PC
    return __get_latest_release(available_releases=releases, python_version=PYTHON_VERSION, ue_type=ue_type,
                                os_name=__get_os_name())


def _check_for_newer_release_on_artifactory(available_releases, latest_release_on_uepc, ue_type):
    """
    Check for newer release on artifactory

    :param available_releases: available releases
    :param latest_release_on_uepc: latest release on UE PC
    :param ue_type: UE type
    :return: newer release
    """
    latest_release = __get_latest_release(available_releases, PYTHON_VERSION, ue_type, __get_os_name(),
                                          latest_release=latest_release_on_uepc)
    return latest_release


def _get_release_info(search_through, release_validator):
    """
    Get matching release

    :param search_through: Expression in which release validator will search for release info
    :param release_validator: Release validator (use _build_release_validation_re() to create one)
    :return ReleasePackage: Release info if match exists, otherwise None
             Example: ReleasePackage('ver'= '1.12.0',
                                     'python_ver'= '38',
                                     'os_name'= 'win',
                                     'ue_type'= 'android',
                                     'os_ver'= '0.12.0',
                                     'rel_format'= 'pyz'}
    """
    if search_through and release_validator:
        match = release_validator.search(search_through)
        if match:
            return ReleasePackage(ver=match.group(2),
                                  python_ver=match.group(3),
                                  os_name=match.group(4),
                                  ue_type=match.group(5),
                                  os_ver=match.group(6),
                                  rel_format=match.group(7))
    else:
        logger.log(f"Can not get release info! "
                   f"Searching through: {search_through}, using release validator: {release_validator}", logging.INFO)
    return None


def _get_server_path(for_storing):
    """
    Get path where server data is stored

    :param for_storing: specify what data you need path for
    :return: server path
    """
    run_folder = _get_server_storage()
    storage_location = os.path.join(run_folder, for_storing)
    return storage_location


def _get_release_path(rel_filename):
    """
    Get release path

    :param rel_filename: release filename
    :return: release path
    """
    release_file_location = _get_server_path(for_storing="releases")
    release_filename_path = os.path.join(release_file_location, rel_filename)
    return release_filename_path


def _get_release_logs_path(rel_filename, port):
    """
    Get logs path for release

    :param rel_filename: release filename
    :param port: port
    :return: logs path
    """
    logs_location = _get_server_path(for_storing="logs")
    logs_path = os.path.join(logs_location,
                             f"{datetime.datetime.now().strftime('%H%M%S_%Y%m%d')}_{rel_filename}.{port}")
    return logs_path


def _create_release_logs_path(rel_filename, port):
    """
    Create logs path for release

    :param rel_filename: release filename
    :param port: port
    :return: logs path
    """
    logs_path = _get_release_logs_path(rel_filename, port)
    if not os.path.exists(logs_path):
        os.mkdir(logs_path)
    return logs_path


def _get_release_console_log_path(rel_filename, port):
    """
    Get path to console.log file for release

    :param rel_filename: release filename
    :param port: port
    :return: path to console.log file
    """
    logs_path = _create_release_logs_path(rel_filename, port)
    console_log_path = os.path.join(logs_path, "console.log")
    return console_log_path


def clear_log_folder():
    """
    Clear log folder under two conditions:
    Files more than logs_storage_limit
    Files older than logs_storage_duration

    :return: None
    """
    directory_path = _get_server_path("logs")
    file_names = os.listdir(directory_path)
    _clear_old_logs(file_names, directory_path)

    while _get_subdirectories_quantity(directory_path) > logs_storage_limit > 0:   # value from when mngr should delete logs folder
        file_names = os.listdir(directory_path)
        oldest = _find_oldest_logs(file_names)
        logger.log(f"Removing logs: {oldest}", logging.INFO)
        try:
            shutil.rmtree(os.path.join(directory_path, oldest))
        except Exception as exc:
            logger.log(f"There was a problem with removing: {oldest}. See: {exc}", logging.INFO)
            break
        try:
            os.remove(os.path.join(directory_path, oldest+".zip"))
        except Exception as exc:
            logger.log(f"There was a problem with removing: {oldest}.zip. See: {exc}", logging.INFO)  # noqa: T201
            break


def _get_subdirectories_quantity(directory_path):
    logs_count = 0
    for item in os.listdir(directory_path):
        item_path = os.path.join(directory_path, item)
        if os.path.isdir(item_path):
            logs_count += 1
    return logs_count


def _find_oldest_logs(file_names):
    file_names = [filename for filename in file_names if not filename.endswith("zip")]
    oldest = file_names[0]
    for filename in file_names:
        oldest_date = oldest[:15].split("_")
        filename_date = filename[:15].split("_")
        if filename_date[1] < oldest_date[1]:
            oldest = filename
        elif filename_date[1] == oldest_date[1]:
            if filename_date[0] < oldest_date[0]:
                oldest = filename
    return oldest


def _clear_old_logs(file_names, directory_path):
    global logs_storage_duration
    now = datetime.date.today()
    storage_duration_limit = datetime.timedelta(days=logs_storage_duration)
    any_storage_duration = datetime.timedelta(days=0)
    for filename in file_names:
        if not filename.endswith("zip"):
            try:
                filename_date = datetime.datetime.strptime(filename[:15], '%H%M%S_%Y%m%d').date()
            except Exception as exc:
                logger.log(f"There was a problem with removing: {filename}. See: {exc}", logging.WARNING)
                continue
            if now - filename_date > storage_duration_limit > any_storage_duration:
                logger.log(f"Removing old logs: {filename}", logging.INFO)
                try:
                    shutil.rmtree(os.path.join(directory_path, filename))
                except Exception as exc:
                    logger.log(f"There was a problem with removing: {filename}. See: {exc}", logging.WARNING)
                try:
                    os.remove(os.path.join(directory_path, filename+".zip"))
                except Exception as exc:
                    logger.log(f"There was a problem with removing: {filename}.zip. See: {exc}", logging.WARNING)


async def _check_android_naa_protocol_can_start(ue_type: str):
    """
    Check if ongoing start of ueproxy with android ue_type can be run with selected NAA protocol.
    Checking will prevent to start any socketio-based NAA protocol with usb_byte protocol on UE_PC.

    :param ue_type: ue type
    """
    global ueproxy_naa_protocol
    if ue_type == "android":  # UE-proxy going to be started with Android access layer
        existing_android_ueproxies = [element for element in await shared_db.naa_protocol.get_all()
                                      if element.access in {"android", "any"}]
        for existing_ueproxy in existing_android_ueproxies:
            # Here possible scenario with many Android ueproxy allows only with naa_protocol="usb_byte".
            # For NAA protocol "socketio" only one Android ueproxy is allowed.
            if ueproxy_naa_protocol == "socketio" or existing_ueproxy.naa_protocol == "socketio":
                msg = (f"Another Android ueproxy is already running on port={existing_ueproxy.port} with NAA protocol "
                       f"'{existing_ueproxy.naa_protocol}'. Another ueproxy startup blocked!")
                if not await check_ueproxy_running_on_port(existing_ueproxy.port):
                    await shared_db.naa_protocol.remove_by_port(existing_ueproxy.port)
                    continue
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=msg)


def _clear_shiv_root_dir(ue_type: str = None):
    """
    Clear shiv root directory

    :param str ue_type: ue type
    """
    user_home_dir = os.path.expanduser("~")
    shiv_dir = os.path.join(user_home_dir, ".shiv")
    if not os.path.exists(shiv_dir):
        logger.log(f"Shiv root directory does not exist `{shiv_dir}`", logging.DEBUG)
        return
    for file in os.listdir(shiv_dir):
        if not ue_type or f"-{ue_type}-" in file:  # on MNGR process startup, it clears all shiv cache files
            absolute_element_path = os.path.join(shiv_dir, file)
            try:
                if os.path.isdir(absolute_element_path):
                    shutil.rmtree(absolute_element_path, ignore_errors=True)
                else:
                    os.remove(absolute_element_path)
            except PermissionError:
                logger.log(f"Permission denied while removing `{file}` from `.shiv`", logging.DEBUG)
            except Exception as e:
                # this is auxilinary function, it supposes to NOT crash MNGR process
                logger.log(f"Error while removing `{file}` from `.shiv`: {e}", logging.ERROR)


def _assert_release_file_exists(rel_filename):
    """
    Check if release file exists at server

    :param rel_filename: release filename
    """
    release_filename_path = _get_release_path(rel_filename)
    if not os.path.isfile(release_filename_path):
        reason = f"{rel_filename} not exists at server"
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=reason)


def _assert_url_not_occupied(ueproxy_url, rel_filename):
    """
    Check if ueproxy_url is not occupied by another release

    :param ueproxy_url: url to check
    :param rel_filename: release filename
    """
    if ueproxy_pool:
        for ue_type in list(ueproxy_pool.services.keys()):
            if not ueproxy_pool.services.get(ue_type):
                continue
            details = ueproxy_pool.services[ue_type].info
            if details and details.service.url == ueproxy_url:  # TODO: 127.0.0.1 == localhost
                port = ueproxy_pool.get_service_port(ue_type)
                occupied_info = f"{details.service.url} is already used by" \
                                f" {details.service.release} running on port={port} with PID={details.service.pid}"
                reason = f"{rel_filename} failed to start - {occupied_info}"
                raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=reason)


async def _start_pyz_release(python_ver, ueproxy_url, port, rel_filename, ue_type=None):
    """
    Start release being python zip file - .pyz

    You start it via:  python <release>.pyz <options>
    """
    global is_any_pyz_started, PROXY_MNGR_PYZ_STARTUP_AWAIT_DELAY, PROXY_MNGR_PYZ_STARTUP_AWAIT_DELAY_FIRST_TIME, \
        pyz_start_timeout
    await_delay_to_ueproxy_start = PROXY_MNGR_PYZ_STARTUP_AWAIT_DELAY if is_any_pyz_started else \
        PROXY_MNGR_PYZ_STARTUP_AWAIT_DELAY_FIRST_TIME
    release_filename_path = _get_release_path(rel_filename)
    pyexe = sys.executable  # future: may run any python aligned with pyver in release (find if such python is on server)
    # TODO: validate if we have correct python version to use for release (now just print)
    logger.log(f"{rel_filename} should start via {python_ver}; using {pyexe}", logging.INFO)

    if ue_type:
        ue_type = "at" if ue_type == "atcmd" else ue_type
        args = [release_filename_path, '--port', str(port), '--ue_type', ue_type]
    else:
        args = [release_filename_path, '--port', str(port)]
    if ssl_files['ssl_certfile']:
        args.extend(['--ssl_keyfile', ssl_files['ssl_keyfile'], '--ssl_certfile', ssl_files['ssl_certfile']])
    if ueproxy_config:
        args.extend(['--config', ueproxy_config])
    # TODO: run inside venv with correct python ver
    start_time = time.time()
    # We need subprocess stdout/stderr log during startup - when something fails we can see why it happened.
    # After successful startup we will have location of ueproxy logs, so any failure reason may be found there.
    logs_path = _create_release_logs_path(rel_filename, port)
    console_log_filename = _get_release_console_log_path(rel_filename, port)
    clear_log_folder()
    args.extend(['--log', logs_path])
    args.extend(['--naa_protocol', ueproxy_naa_protocol])
    if at_ue_manager and ue_type.lower() in ['quectel']:
        args.extend(['--at_ue_manager'])
    if stream_logs:
        args.extend(['--stream_logs'])
    logger.log(f"Start ueproxy service with following parameters: {args}", logging.INFO)
    console_log = open(console_log_filename, "w")  # TODO: change to rotating file with small size
    try:
        proc = await asyncio.create_subprocess_exec(pyexe, *args,
                                                    stdout=console_log,
                                                    stderr=asyncio.subprocess.STDOUT)
        pid = proc.pid
        logger.log(f"Await {await_delay_to_ueproxy_start}s for ueroxy service ({pid=}) startup", logging.DEBUG)
        await asyncio.sleep(await_delay_to_ueproxy_start)
        # connect to UE-proxy and get it's service info (ver, access layer, start_time, logs)
        # extend this data with release and PID
        logger.log(f"Ueproxy service process started with following PID: {pid}", logging.DEBUG)
        logger.log(f"Awaiting ueproxy service ({pid=}) to be ready within {pyz_start_timeout}s", logging.DEBUG)
        ue_proxy_info = await _get_ueproxy_service_details(rel_filename, ueproxy_url, timeout=int(pyz_start_timeout))

        details = ServiceDetails(service={'pid': pid, 'release': rel_filename, 'url': ueproxy_url},
                                 access_layer=f"{ue_proxy_info['plugin']['details']['name']};"
                                              f"ver.{ue_proxy_info['plugin']['details']['version']}",
                                 bootup_duration=time.time() - start_time,
                                 start_time=datetime.datetime.now(),
                                 logs=ue_proxy_info['logs']
                                 )
        logger.log(f"Ueproxy service started on following port: {port}", logging.INFO)
    except HTTPException as err:
        await asyncio.sleep(0.5)  # give chance to ueproxy process for flushing console data into file
        logger.log(f": HTTPException raised during starting ueproxy service: {err}", logging.INFO)
        console_log.close()
        await _terminate_the_process(proc)  # Terminate the process to release the used port
        ueproxy_pool.delete_service(ue_type)
        with open(console_log_filename, "r") as startup_log:
            content = startup_log.read()
            err.detail = f"{err.detail}\nUE-PROXY BOOTUP:\n{content}"
            raise
    except Exception:
        console_log.close()
        if 'proc' in locals():
            await _terminate_the_process(proc)
            ueproxy_pool.delete_service(ue_type)
        raise

    return pid, proc, details, console_log


# flake8: noqa: C901
async def _get_ueproxy_service_details(rel_filename, ueproxy_url, timeout):
    """
    Get ueproxy service details from ueproxy service via httpx client

    :param rel_filename: release filename
    :param ueproxy_url: ueproxy service url
    :param timeout: timeout for ueproxy service to start
    :return: ueproxy service details
    """
    # Split summary timeout into connect and request (httpx general) timeouts
    global is_any_pyz_started
    timeout_request = 15.0 if is_any_pyz_started else 20.0
    timeout_connect = timeout - timeout_request
    is_any_pyz_started = True

    start_time = time.monotonic()
    # connection via httpx client may fail since there is nothing yet to connect to because
    # shiv is still unpacking .pyz and launching ueproxy
    trials_duration = 0.0

    if ueproxy_url.startswith('https:'):
        ssl_verify = ssl_files['ssl_client_certbundle'] if ssl_files['ssl_client_certbundle'] else False
    else:
        ssl_verify = ssl.CERT_NONE
    while trials_duration < timeout_connect + timeout_request:
        try:
            return await _request_ueproxy_service_details(ssl_verify, ueproxy_url, timeout_request, timeout_connect,
                                                          trials_duration)
        except httpx.ConnectError as err:
            trials_duration = time.monotonic() - start_time
            if trials_duration > timeout:
                reason = f"ERROR: {rel_filename} failed to start - can't connect {ueproxy_url}: {err!r}"
                raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=reason)
        except httpx.TimeoutException:
            trials_duration = time.monotonic() - start_time
            if trials_duration > timeout:
                reason = f"TIMEOUT: {rel_filename} failed to start within {timeout} seconds - can't connect {ueproxy_url}"
                raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=reason)
        time.sleep(5) # wait before next trial
    reason = f"TIMEOUT: {rel_filename} failed to start within {timeout} seconds - can't connect {ueproxy_url}"
    raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=reason)


async def _request_ueproxy_service_details(ssl_verify, ueproxy_url, timeout_request, timeout_connect, trials_duration):
    remaining_connect_timeout = timeout_connect - trials_duration
    httpx_timeout = httpx.Timeout(timeout_request, connect=remaining_connect_timeout)
    logger.log("Check if ueproxy service is ready by calling endpoint /about", logging.DEBUG)
    ac_kwargs = {
        "timeout": httpx_timeout,
        "verify": ssl_verify,
        "base_url": ueproxy_url,
    }

    if Version(httpx.__version__) <= Version('0.27.0'):
        proxies = {
            "http://": None,
            "https://": None,
        }
        ac_kwargs.update(proxies=proxies)
    else:
        transport = httpx.AsyncHTTPTransport(proxy=None)
        ac_kwargs.update(transport=transport)

    async with httpx.AsyncClient(**ac_kwargs) as client:
        response = await client.get("/about")
        service_details = response.json()
        if response.status_code == 200:
            return service_details
        raise HTTPException(status_code=response.status_code, detail=service_details)


def _build_release_validation_re(prefix='', suffix=''):
    """
    Build regular expression for release validation

    :param prefix: prefix for regular expression
    :param suffix: suffix for regular expression
    :return: compiled regular expression
    """
    tool_name = r'ueproxy'
    tool_ver = r'\d+\.\d+\.\d+'
    python_ver = r'\d{2,3}'
    os_name = r'macos|win|linux'
    os_ver = r'\S+'
    ue_type = r'android|iphone|mtk|fastmile|at|quectel|simcom|sequans'
    file_extension = r'pyz|exe'
    filtering_groups = r'(' + tool_name + r')\-(' + tool_ver + r')\-py(' + python_ver + r')\-(' + os_name + r')-(' \
                       + ue_type + ')-(' + os_ver + r')' + r'\.(' + file_extension + r')'
    rel_re = prefix + filtering_groups + suffix
    validator = re.compile(rel_re)
    return validator


def _get_server_storage():
    """
    Get location of server files

    :return: location of server files
    """
    # we want it to be user independent
    uepc_files_location = os.path.join(os.getcwd(), ".ueproxyservice")
    if not os.path.exists(uepc_files_location):
        os.mkdir(uepc_files_location)
    if not os.path.isdir(uepc_files_location):
        raise AttributeError(f"{uepc_files_location} should be directory")
    return uepc_files_location


def _get_server_files():
    """List of files used by server"""
    location = _get_server_storage()
    paths = []
    for folder, subs, files in os.walk(location):
        for filename in files:
            paths.append(os.path.join(folder, filename))
    return paths


def _report_incorrect_release_format(release_filename, expected_format):
    """
    Report incorrect release format

    :param release_filename: release filename
    :param expected_format: expected format
    """
    reason = f"{release_filename} has incorrect format - should follow: {expected_format}"
    raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=reason)


def __get_process_by_pid(pid_value):
    """Get psutil.Process instance by PID"""
    try:
        return psutil.Process(pid_value)
    except psutil.NoSuchProcess:
        return None


def __kill_subprocesses(children):
    """Kill all subprocesses of the given process"""
    for child in children:
        __kill_process_ignore_error(process_to_kill=child)


def __kill_process_ignore_error(process_to_kill):
    """Kill still existing process and ignore errors"""
    if psutil.pid_exists(process_to_kill.pid):
        logger.log(f"Will kill process - PID: {process_to_kill.pid}", logging.INFO)
        try:
            if os.name == "nt":
                process_to_kill.kill()
            else:
                process_to_kill.send_signal(signal.SIGTERM)
        except (ProcessLookupError, psutil.NoSuchProcess):
            pass


async def _shutdown_process_and_subprocesses(ue_type, pid, shutdown_timeout=10):
    """Shutdown procedure with graceful shutdown and force kill if needed"""
    parent_process = __get_process_by_pid(pid)
    if parent_process:
        children_processes = parent_process.children(recursive=True)
        await _request_ueproxy_stop(ue_type)  # try graceful shutdown as the first attempt
        process_gone = await _pid_is_gone(pid, timeout=shutdown_timeout)
        __kill_subprocesses(children_processes)  # ensure with force kill try as the second attempt
        __kill_process_ignore_error(process_to_kill=parent_process)
        return process_gone
    return False


async def _stop_service(port, timeout=10, kill=False):
    """
    Stop service

    If kill==False then try graceful shutdown first

    CAUTION: pid may change if restart requested via ue-proxy JSON-RPC - maybe scan 'ps' for port (via psutil?)
    """
    if not kill:
        gone = False
        for ue_type in list(ueproxy_pool.services.keys()):
            if port == ueproxy_pool.get_service_port(ue_type):
                pid = ueproxy_pool.services[ue_type].info.service.pid
                logger.log(f"Will stop {ueproxy_pool.services[ue_type].info.service.release}"
                           f" running at port={port} - PID: {pid}", logging.INFO)
                gone = await _shutdown_process_and_subprocesses(ue_type=ue_type, pid=pid, shutdown_timeout=timeout)
        if gone:
            ports = await shared_db.naa_protocol.get_all_ports()
            logger.log(f"Service at port={port} stopped successfully, cached in db: {ports}", logging.INFO)
            if port in ports:
                await shared_db.naa_protocol.remove_by_port(port)
            return
    # Ensure cached asyncio.subprocess is finished otherwise kill it
    for ue_type in list(ueproxy_pool.services.keys()):
        if port == ueproxy_pool.get_service_port(ue_type):
            try:
                ueproxy_pool.services[ue_type].process.kill()
            except ProcessLookupError:
                pass
            ports = await shared_db.naa_protocol.get_all_ports()
            logger.log(f"Service at port={port} stopped successfully, cached in db: {ports}", logging.INFO)
            if port in ports:
                await shared_db.naa_protocol.remove_by_port(port)


async def _request_ueproxy_stop(ue_type):
    """
    Request ue-proxy to stop

    :param port: port number
    :return: True if ue-proxy stopped, False otherwise
    """
    ueproxy_url = ueproxy_pool.services[ue_type].info.service.url
    try:
        async with httpx.AsyncClient() as client:
            response = await client.post(f"{ueproxy_url}/stop_ue_proxy")
            if response.status_code == 200:
                return True
            return False
    except httpx.ConnectError:
        return False
    except httpx.TimeoutException:
        return False


async def _terminate_the_process(process):
    """
    Terminate the process and wait until the process exit

    :param process: Process object
    """
    process.terminate()
    await process.wait()


def _remove_console_log(port):  # TODO: uncomment original method
    """
    Remove console log file

    :param port: port number
    """
    console_log = ueproxy_pool.services[port]['console']
    console_log.close()
    os.remove(console_log.name)  # TODO: maybe return last 10 lines from console_log as result of stop_service()


def _remove_redundant_proxy_releases(release_validator):
    """
    Remove redundant releases

    :param release_validator: regex to validate release name
    """
    ueproxy_storage = _get_releases()
    releases = {}
    for ueproxy_name in ueproxy_storage:
        rel_info = _get_release_info(search_through=ueproxy_name, release_validator=release_validator)
        package_type = _create_release_package_name(rel_info)
        if package_type not in releases:
            releases[package_type] = []
        releases[package_type].append((rel_info.ver, rel_info.os_ver, 'ueproxy'))
    __sort_releases(releases)
    for release in releases:
        # keep the latest release
        if len(releases[release]) > 1:
            for rel_filename in releases[release][:-1]:
                __remove_ueproxy_release(rel_filename[2])


def _zip_folder(folder_path, zip_file_path):
    if os.path.exists(folder_path):
        with ZipFile(zip_file_path, 'w') as zip_file:
            for folder_root, _, files in os.walk(folder_path):
                for file in files:
                    file_path = os.path.join(folder_root, file)
                    relative_path = os.path.relpath(file_path, folder_path)
                    zip_file.write(file_path, relative_path)
    else:
        raise OSError(f"Catalogue {folder_path} does not exist!")


async def _await_for_state(state, ue_type, ueproxy_service, timeout, interval):
    end_time = time.time() + timeout
    while time.time() < end_time:
        if ue_type in ueproxy_pool.services and ueproxy_service.status == state:
            return ueproxy_pool.services[ue_type]
        else:
            await asyncio.sleep(interval)


def __select_matched_logs(logs, port, ue_type):
    matched_logs = []
    for log in logs:
        if re.findall(fr".{port}", log) and re.findall(fr".*-{ue_type}-.*".lower(), log):
            matched_logs.append(log)
    return matched_logs


async def _await_for_state(state, ue_type, ueproxy_service, timeout, interval):
    end_time = time.time() + timeout
    while time.time() < end_time:
        if ue_type in ueproxy_pool.services and ueproxy_service.status == state:
            return ueproxy_pool.services[ue_type]
        else:
            await asyncio.sleep(interval)


def __sort_releases(releases):
    """Sort releases by tool_ver and access_ver"""
    for release in releases:
        releases[release].sort(key=lambda x: (Version(x[0]), Version(x[1])))


def __remove_ueproxy_release(rel_filename):
    """Remove release from storage"""
    release_filename_path = _get_release_path(rel_filename)
    if os.path.isfile(release_filename_path):
        logger.log(f"removing release: {rel_filename}", logging.INFO)  # noqa: T201
        os.remove(release_filename_path)
    else:
        reason = f"{rel_filename} not found while trying to remove"
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=reason)


async def __get_ueproxy_with_specific_access_layer_if_is_running(ue_type: str, timeout: int = 20,
                                                                 interval: float = 0.5):
    """
    Get ueproxy service with requested access layer if once is already running

    :param ue_type: requested service access layer
    :param timeout: ueproxy state update timeout
    :param interval: ueproxy state update interval
    :return: service details if service is running, {} otherwise
    """
    ueproxy_service = ueproxy_pool.get_service(ue_type)
    if ueproxy_service:
        if ueproxy_service.status == ProxyServiceStatus.ACTIVE:
            return ueproxy_service

        elif ueproxy_service.status in (ProxyServiceStatus.STARTING, ProxyServiceStatus.DELETING):
            if await _await_for_state(ProxyServiceStatus.ACTIVE, ue_type, ueproxy_service, timeout, interval):
                return ueproxy_pool.services[ue_type]

        elif ueproxy_service.status == ProxyServiceStatus.INACTIVE:
            ueproxy_service.status = ProxyServiceStatus.DELETING
            if ue_type in ueproxy_pool.services:
                try:
                    port = ueproxy_pool.get_service_port(ue_type)
                    await _stop_service(port, timeout=10)
                    ueproxy_pool.delete_service(ue_type)
                except Exception:
                    ueproxy_service.status = ProxyServiceStatus.INACTIVE
    return {}


def __get_latest_release(available_releases, python_version, ue_type, os_name, latest_release=None):
    """
    Get matching release

    :param List[str] available_releases: List of available releases
    :param str python_version: Required python version
    :param str ue_type: Required ue type
    :param str os_name: Required os name
    :param str latest_release: Latest release name to compare with available releases
    :return Optional[str]: Release name if latest one is available, otherwise None.
             Example: 'ueproxy-1.11.0-win-android-0.12.0.pyz'
    """
    release_validator = _build_release_validation_re()
    logger.log(f"Latest release must meet: py_ver={python_version}, ue_type={ue_type}"
               f" os_name={os_name}", logging.DEBUG)
    for release in available_releases:
        release_info = _get_release_info(search_through=release, release_validator=release_validator)
        if release_info:
            if latest_release:
                latest_release_info = _get_release_info(search_through=latest_release,
                                                        release_validator=release_validator)
                if latest_release_info:
                    if python_version == release_info.python_ver == latest_release_info.python_ver and \
                            ue_type == release_info.ue_type == latest_release_info.ue_type and \
                            os_name == release_info.os_name == latest_release_info.os_name:
                        if Version(release_info.ver) > Version(latest_release_info.ver) or \
                                Version(release_info.ver) == Version(latest_release_info.ver) and \
                                Version(release_info.os_ver) > Version(latest_release_info.os_ver):
                            latest_release = release
            else:
                if python_version == release_info.python_ver and ue_type == release_info.ue_type and \
                        os_name == release_info.os_name:
                    latest_release = release
                else:
                    logger.log(f"Release not ok (py_ver={release_info.python_ver}, ue_type={release_info.ue_type}"
                               f" os_name={release_info.os_name})", logging.DEBUG)
        else:
            logger.log(f"Release {release} does not meet the requirements!", logging.DEBUG)
    if not latest_release:
        logger.log(f"No latest release in available: \n{available_releases}", logging.WARNING)
    return latest_release


async def _pid_is_gone(pid, timeout=5):
    """
    Check if process is gone within timeout

    :param pid: process id
    :param timeout: timeout in seconds
    :return: True if process is gone, False otherwise
    """
    start_time = time.time()
    while True:
        if not psutil.pid_exists(pid):
            return True
        await asyncio.sleep(0.1)
        awaiting_duration = time.time() - start_time
        if awaiting_duration > timeout:
            return False


def __configure_proxy_mngr_artifactory_url(proxy_mngr_artifactory: Union[None, str]):
    """
    Configure artifactory url base on function argument(from cli or config file) or env variable

    :param Union[None, str] proxy_mngr_artifactory: link to artifactory
    """
    global PROXY_MNGR_ARTIFACTORY, is_custom_artifactory
    if proxy_mngr_artifactory is not None and proxy_mngr_artifactory != "":
        PROXY_MNGR_ARTIFACTORY = proxy_mngr_artifactory
        is_custom_artifactory = True
    elif env_proxy_mngr_artifactory := os.environ.get("PROXY_MNGR_ARTIFACTORY", ""):
        PROXY_MNGR_ARTIFACTORY = env_proxy_mngr_artifactory
        is_custom_artifactory = True

    __validate_proxy_mngr_artifactory_url()


def __validate_proxy_mngr_artifactory_url():
    """Check whether value of PROXY_MNGR_ARTIFACTORY is set properly"""
    if not PROXY_MNGR_ARTIFACTORY.startswith(("https://", "http://")):
        raise AttributeError("PROXY_MNGR_ARTIFACTORY path suppose to begin with 'https://' or 'http://'")


def __remove_directory_with_content_if_exists(path):
    """
    Remove directory with content if exists

    :param path: Resource to remove path
    """
    if os.path.exists(path):
        shutil.rmtree(path)


def __create_directory_if_not_exist(path):
    """
    Create directory if specified one does not exist

    :param path: Directory to create path
    :return:
    """
    if not os.path.exists(path):
        os.makedirs(path)


def __get_latest_created_catalogue_from(selected_catalogues, path):
    """
    Get latest catalogue from selected list of catalogues in specified path

    :param selected_catalogues: List of selected catalogues
    :param path: Path to selected catalogues
    :return: Catalogue name
    """
    if os.path.exists(path) and selected_catalogues:
        return max(selected_catalogues, key=lambda catalogue: os.path.getmtime(os.path.join(path, catalogue)))
    return None


def _check_windows_long_paths_enabled(logger):
    """Check if LongPathsEnabled is turned on in Windows."""
    if not (platform.system() == "Windows"):
        return
    try:
        import winreg
        registry_key = winreg.OpenKey(
            winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Control\FileSystem", 0, winreg.KEY_READ)
        value, regtype = winreg.QueryValueEx(registry_key, "LongPathsEnabled")
        winreg.CloseKey(registry_key)
        if value == 1:
            logger.log("Windows path length limitation is disabled.", logging.DEBUG)
        else:
            logger.log(
                "Windows path length limitation is enabled. The PYZ packages might not start correctly. More info: "
                "https://confluence.ext.net.nokia.com/display/AbstractLibs/Problem+with+starting+PYZ+packages",
                logging.WARNING)
    except Exception as exe:
        logger.log(f"Could not check LongPathsEnabled. Exception: {exe}", logging.DEBUG)


def _configure_api_external_loggers():
    """
    Configure external loggers for the API.

    This function sets up logging for external libraries used by the API, such as 'uvicorn' and 'uvicorn.access'.
    It ensures that logs from these libraries are captured and handled appropriately.
    """
    loggers = ['uvicorn', 'uvicorn.access']
    for log in loggers:
        _logger = logging.getLogger(log)
        in_memory_handler = InMemoryHandler()
        _logger.addHandler(in_memory_handler)
        _logger.setLevel(logging.INFO)
    loggers.append(logger)


